1	export type Item = {
2	  type: string;
3	  cursed?: boolean;
4	  enchantment?: number;
5	};
6	
7	export type QuoteStep = {
8	  op: string;
9	  items: Item[];
10	};
11	
12	export type Damage = {
13	  itemType: string;
14	  amount: number;
15	};
16	
17	export type Incident = {
18	  cause: string;
19	  damages: Damage[];
20	};
21	
22	export type ClaimStep = {
23	  op: string;
24	  policy: number;
25	  incident: Incident;
26	};
27	
28	export type Step = QuoteStep | ClaimStep;
29	
30	export type Customer = {
31	  yearsWithMHPCO: number;
32	};
33	
34	export type Scenario = {
35	  customer: Customer;
36	  steps: Step[];
37	};
38	
39	export type QuoteResult = {
40	  premium: number;
41	};
42	
43	export type ClaimResult = {
44	  payout: number;
45	  remainingCap: number;
46	};
47	
48	export type StepResult = QuoteResult | ClaimResult;
49	
50	export type ScenarioOutcome = {
51	  results: StepResult[];
52	};
53	
54	const PROCESSING_FEE = 5;
55	
56	const BASE_PREMIUMS: Record<string, number> = {
57	  sword: 100,
58	  amulet: 60,
59	  staff: 80,
60	  potion: 40,
61	  rune: 25,
62	  moonstone: 25,
63	};
64	
65	const FIRST_INSURANCE_PERCENT = 10;
66	
67	// Multiply before dividing: `amount * 1.1` drifts (115.00000000000001) and
68	// Math.ceil turns the drift into a whole extra gold piece. The spec requires
69	// intermediates to stay exact, so every percentage goes through here.
70	const PERCENT_WHOLE = 100;
71	
72	const percentOf = (amount: number, percent: number): number =>
73	  (amount * percent) / PERCENT_WHOLE;
74	
75	// Rounding always favours MHPCO: premiums round up, payouts round down.
76	const roundPremium = (amount: number): number => Math.ceil(amount);
77	
78	const basePremiumOfType = (type: string): number => BASE_PREMIUMS[type];
79	
80	const BLOCK_SIZE = 3;
81	const BLOCK_BASE_PREMIUM = 60;
82	
83	const countByType = (items: Item[]): Map<string, number> => {
84	  const counts = new Map<string, number>();
85	  for (const item of items) {
86	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
87	  }
88	  return counts;
89	};
90	
91	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
92	
93	// A building block is exactly 3 alike components. Blocks are only offered on
94	// components, never on main items, and only at exactly 3 — 4 runes are priced
95	// per item, not as a block plus one.
96	const formsBuildingBlock = (type: string, count: number): boolean =>
97	  COMPONENT_TYPES.has(type) && count === BLOCK_SIZE;
98	
99	// A group of alike items is priced as a building block if it forms one, and
100	// per item otherwise.
101	const groupBasePremiumOf = (type: string, count: number): number =>
102	  formsBuildingBlock(type, count)
103	    ? BLOCK_BASE_PREMIUM
104	    : count * basePremiumOfType(type);
105	
106	// The policy base premium is the sum of the base premiums of each group of
107	// alike items.
108	const policyBasePremiumOf = (items: Item[]): number =>
109	  [...countByType(items)].reduce(
110	    (total, [type, count]) => total + groupBasePremiumOf(type, count),
111	    0,
112	  );
113	
114	// Item-specific surcharges are additive percentages of the affected item's OWN
115	// base premium — they never compound with each other, and never apply to the
116	// policy total.
117	const CURSE_PERCENT = 50;
118	const HIGH_ENCHANTMENT_PERCENT = 30;
119	const HIGH_ENCHANTMENT_THRESHOLD = 5;
120	
121	const isCursed = (item: Item): boolean => item.cursed === true;
122	
123	const isHighlyEnchanted = (item: Item): boolean =>
124	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
125	
126	const surchargePercentOf = (item: Item): number =>
127	  (isCursed(item) ? CURSE_PERCENT : 0) +
128	  (isHighlyEnchanted(item) ? HIGH_ENCHANTMENT_PERCENT : 0);
129	
130	const itemSurchargesOf = (items: Item[]): number =>
131	  items.reduce(
132	    (total, item) =>
133	      total + percentOf(basePremiumOfType(item.type), surchargePercentOf(item)),
134	    0,
135	  );
136	
137	const LOYALTY_PERCENT = 20;
138	const LOYALTY_THRESHOLD_YEARS = 2;
139	const FOLLOW_UP_CONTRACT_PERCENT = 15;
140	
141	const isLongStanding = (customer: Customer): boolean =>
142	  customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS;
143	
144	// Policy-wide modifiers are additive percentages of the policy base premium:
145	// they never compound with each other. A discount is simply a negative
146	// percentage, so surcharges and discounts sum in a single list.
147	const policyModifierPercentOf = (
148	  customer: Customer,
149	  isFollowUpContract: boolean,
150	): number =>
151	  FIRST_INSURANCE_PERCENT +
152	  (isLongStanding(customer) ? -LOYALTY_PERCENT : 0) +
153	  (isFollowUpContract ? -FOLLOW_UP_CONTRACT_PERCENT : 0);
154	
155	const quoteStep = (
156	  step: QuoteStep,
157	  customer: Customer,
158	  isFollowUpContract: boolean,
159	): QuoteResult => {
160	  const basePremium = policyBasePremiumOf(step.items);
161	  const policyModifiers = percentOf(
162	    basePremium,
163	    policyModifierPercentOf(customer, isFollowUpContract),
164	  );
165	
166	  return {
167	    premium: roundPremium(
168	      basePremium +
169	        itemSurchargesOf(step.items) +
170	        policyModifiers +
171	        PROCESSING_FEE,
172	    ),
173	  };
174	};
175	
176	const INSURANCE_VALUES: Record<string, number> = {
177	  sword: 1000,
178	  amulet: 600,
179	  staff: 800,
180	  potion: 400,
181	  rune: 250,
182	  moonstone: 250,
183	};
184	
185	const DEDUCTIBLE = 100;
186	const CAP_MULTIPLIER = 2;
187	
188	// Rounding always favours MHPCO: payouts round down.
189	const roundPayout = (amount: number): number => Math.floor(amount);
190	
191	const insuranceSumOf = (items: Item[]): number =>
192	  items.reduce((sum, item) => sum + INSURANCE_VALUES[item.type], 0);
193	
194	// A policy is created by a quote step and accumulates claims against its cap.
195	type Policy = {
196	  items: Item[];
197	  remainingCap: number;
198	};
199	
200	const isClaimStep = (step: Step): step is ClaimStep => step.op === "claim";
201	
202	const claimStep = (step: ClaimStep, policy: Policy): ClaimResult => {
203	  const desired = step.incident.damages.reduce(
204	    (total, damage) => total + (damage.amount - DEDUCTIBLE),
205	    0,
206	  );
207	  const payout = roundPayout(desired);
208	
209	  policy.remainingCap -= payout;
210	
211	  return { payout, remainingCap: policy.remainingCap };
212	};
213	
214	export const runScenario = (scenario: Scenario): ScenarioOutcome => {
215	  const policies = new Map<number, Policy>();
216	  let quotesSoFar = 0;
217	
218	  const results = scenario.steps.map((step, index): StepResult => {
219	    if (isClaimStep(step)) {
220	      return claimStep(step, policies.get(step.policy) as Policy);
221	    }
222	
223	    const result = quoteStep(step, scenario.customer, quotesSoFar > 0);
224	    quotesSoFar += 1;
225	    policies.set(index, {
226	      items: step.items,
227	      remainingCap: CAP_MULTIPLIER * insuranceSumOf(step.items),
228	    });
229	    return result;
230	  });
231	
232	  return { results };
233	};
