// damage entry rather than once from the incident total.
const reimbursementFor = (damage: Damage): number =>
  damage.amount - DEDUCTIBLE;

const totalReimbursementFor = (incident: Incident): number =>
  incident.damages.reduce(
    (total, damage) => total + reimbursementFor(damage),
    0,
  );

